/**
 * GraphQL query-cost estimator
 *
 * Scores incoming GraphQL queries and rejects requests over a configured
 * budget per token type. Each field in the query contributes to the total
 * cost based on its depth, type (object vs scalar), and whether it introduces
 * list fan-out.
 *
 * The estimator parses the raw query string to produce a cost estimate.
 * Budget is configurable per token type.
 */

// ---- Types -------------------------------------------------------------------

export interface CostBudget {
  /** Maximum allowed cost for a single query */
  maxQueryCost: number;
  /** Maximum allowed cost for a mutation */
  maxMutationCost: number;
  /** Maximum allowed cost for a subscription */
  maxSubscriptionCost: number;
}

export interface CostResult {
  /** Estimated total cost score */
  totalCost: number;
  /** Whether this query fits within its budget */
  allowed: boolean;
  /** Human-readable reason if rejected */
  reason?: string;
  /** Per-operation budget applied */
  budget: number;
}

export class GraphQLCostError extends Error {
  readonly statusCode = 403;
  readonly code = "GRAPHQL_COST_EXCEEDED";

  constructor(
    message: string,
    public readonly cost: number,
    public readonly budget: number,
  ) {
    super(message);
    this.name = "GraphQLCostError";
  }

  toJSON() {
    return {
      error: this.message,
      code: this.code,
      cost: this.cost,
      budget: this.budget,
    };
  }
}

// ---- Default budgets ---------------------------------------------------------

export const DEFAULT_BUDGET: CostBudget = {
  maxQueryCost: 100,
  maxMutationCost: 200,
  maxSubscriptionCost: 500,
};

// ---- Token type cost weights -------------------------------------------------

const FIELD_BASE_COST = 1;
const OBJECT_FIELD_MULTIPLIER = 2;
const LIST_FANOUT_MULTIPLIER = 3;
const DEPTH_PENALTY = 1.5;

// ---- Helpers -----------------------------------------------------------------

type OperationType = "query" | "mutation" | "subscription";

/**
 * Very simple GraphQL query parser that extracts field names, depth,
 * and detects list fields. This is intentionally not a full GraphQL parser;
 * it uses regex analysis that covers the common patterns in the codebase.
 *
 * For production, consider using `graphql` package's `parse()` + AST visitor.
 */

interface ParsedField {
  name: string;
  depth: number;
  isList: boolean;
  hasSubfields: boolean;
  /** Arguments present on this field */
  argCount: number;
}

/** Parse a GraphQL operation string and extract all fields with depth info. */
function parseQueryFields(
  query: string,
): { operationType: OperationType; fields: ParsedField[] } {
  const operationType = extractOperationType(query);
  const fields: ParsedField[] = [];

  // Remove comments
  const cleaned = query
    .replace(/#.*$/gm, "")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .trim();

  if (!cleaned) return { operationType, fields: [] };

  // Strip everything before the first `{` (operation keyword, params, etc.)
  const firstBrace = cleaned.indexOf("{");
  if (firstBrace === -1) return { operationType, fields: [] };

  const body = cleaned.slice(firstBrace);

  // Track field names and their depth by scanning character by character
  let depth = 0;
  let currentField = "";
  let inArgParens = 0;
  let currentArgCount = 0;
  let seenOpeningBraceForField = false;

  for (let i = 0; i < body.length; i++) {
    const ch = body[i];

    if (ch === "(") {
      inArgParens++;
      continue;
    }
    if (ch === ")") {
      inArgParens--;
      // Count arguments: split the inner content by commas
      if (inArgParens === 0 && currentField) {
        const argStart = body.lastIndexOf("(", i);
        if (argStart !== -1) {
          const argContent = body.slice(argStart + 1, i);
          currentArgCount = argContent
            .split(",")
            .filter((a) => a.trim().length > 0 && !a.includes(":"))
            .length;
        }
      }
      continue;
    }

    if (inArgParens > 0) continue;

    // Track field name characters
    if (/[a-zA-Z_]/.test(ch)) {
      currentField += ch;
      continue;
    }

    // When we hit a non-name character after accumulating a field name
    if (currentField) {
      const isKeyword = [
        "query", "mutation", "subscription", "fragment", "on",
        "type", "interface", "true", "false", "null",
      ].includes(currentField);

      if (!isKeyword) {
        const nextCh = body[i] || " ";
        const hasSubfields = nextCh === "{";
        const isNextList = nextCh === "[";

        // Look ahead for arguments if we haven't counted them yet
        const afterField = body.slice(i).trimStart();
        let argCount = currentArgCount;
        if (afterField.startsWith("(")) {
          const closeParen = findMatchingParen(body, i + afterField.indexOf("("));
          if (closeParen !== -1) {
            const argContent = body.slice(i + afterField.indexOf("(") + 1, closeParen);
            argCount = argContent
              .split(",")
              .filter((a) => a.trim().length > 0)
              .length;
          }
        }

        fields.push({
          name: currentField,
          depth: depth,
          isList: isNextList,
          hasSubfields,
          argCount,
        });
      }
      currentField = "";
      currentArgCount = 0;
    }

    if (ch === "{") depth++;
    if (ch === "}") depth--;
  }

  return { operationType, fields };
}

/** Find the matching closing parenthesis for an opening paren at startPos. */
function findMatchingParen(str: string, startPos: number): number {
  let depth = 0;
  for (let i = startPos; i < str.length; i++) {
    if (str[i] === "(") depth++;
    if (str[i] === ")") {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

function extractOperationType(query: string): OperationType {
  const cleaned = query.trim().replace(/#.*$/gm, "").replace(/\s+/g, " ");
  if (/^mutation\b/i.test(cleaned)) return "mutation";
  if (/^subscription\b/i.test(cleaned)) return "subscription";
  return "query";
}

/**
 * Compute a cost score for a parsed set of fields.
 *
 * Cost formula:
 *   fieldCost = BASE_COST × (1 + DEPTH_PENALTY × depth)
 *   if object type: × OBJECT_FIELD_MULTIPLIER
 *   if list: × LIST_FANOUT_MULTIPLIER
 *   + argCount (each argument adds 1 cost unit)
 */
function computeFieldCost(field: ParsedField): number {
  let cost = FIELD_BASE_COST * (1 + DEPTH_PENALTY * (field.depth - 1));

  if (field.hasSubfields) {
    cost *= OBJECT_FIELD_MULTIPLIER;
  }

  if (field.isList) {
    cost *= LIST_FANOUT_MULTIPLIER;
  }

  cost += field.argCount;

  return Math.round(cost * 100) / 100;
}

/**
 * Estimate the cost of a GraphQL query string.
 */
export function estimateQueryCost(query: string): {
  totalCost: number;
  fields: Array<{ name: string; cost: number; depth: number }>;
  operationType: OperationType;
} {
  const { operationType, fields } = parseQueryFields(query);

  const fieldCosts = fields.map((f) => ({
    name: f.name,
    cost: computeFieldCost(f),
    depth: f.depth,
  }));

  const totalCost = fieldCosts.reduce((sum, f) => sum + f.cost, 0);

  return {
    totalCost: Math.round(totalCost * 100) / 100,
    fields: fieldCosts,
    operationType,
  };
}

/**
 * Validate that a query is within budget, throwing if exceeded.
 */
export function validateQueryCost(
  query: string,
  budget: CostBudget = DEFAULT_BUDGET,
): CostResult {
  const { totalCost, operationType } = estimateQueryCost(query);

  const budgetMap: Record<OperationType, number> = {
    query: budget.maxQueryCost,
    mutation: budget.maxMutationCost,
    subscription: budget.maxSubscriptionCost,
  };

  const allowedBudget = budgetMap[operationType];

  if (totalCost > allowedBudget) {
    throw new GraphQLCostError(
      `Query cost ${totalCost} exceeds ${operationType} budget of ${allowedBudget}`,
      totalCost,
      allowedBudget,
    );
  }

  return { totalCost, allowed: true, budget: allowedBudget };
}

/**
 * Integration tests for the full capacity simulation pipeline.
 *
 * Covers the complete flow: ingest → plan → execute → report
 * and edge cases (missing range, network-drop mid-run, unrealistic mix).
 */

import { describe, it, expect, beforeEach, afterEach } from "@jest/globals";
import {
  simulate,
  buildSyntheticCurve,
  ingestFromObject,
  SimulationSafetyError,
} from "../../simulator/index.js";
import type { TrafficCurve } from "../../simulator/types.js";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const BASE_MS = 1_700_000_000_000;

const makeSample = (
  ts: number,
  route: TrafficCurve["samples"][number]["route"] = "slots_list",
  overrides: Partial<TrafficCurve["samples"][number]> = {},
) => ({
  timestampMs: ts,
  route,
  requestCount: 100,
  errorCount: 1,
  p99LatencyMs: 80,
  ...overrides,
});

// ---------------------------------------------------------------------------
// Happy path: full simulation pipeline
// ---------------------------------------------------------------------------

describe("simulate() – happy path", () => {
  it("returns a SimulateResult with all required fields", async () => {
    const curve = buildSyntheticCurve({ sampleCount: 5, peakRps: 10 });
    const result = await simulate({
      curve,
      config: { seed: 1, dryRun: true, scaleFactor: 1.0 },
    });

    expect(result.curve.label).toBe(curve.label);
    expect(result.plan).toBeDefined();
    expect(result.report).toBeDefined();
    expect(result.formattedReport).toContain(curve.label);
    expect(Array.isArray(result.ingestionWarnings)).toBe(true);
  });

  it("returns allWithinBudget=true for a healthy curve", async () => {
    const curve = buildSyntheticCurve({
      sampleCount: 5,
      peakRps: 20,
      errorRateFraction: 0.00001,
    });
    const result = await simulate({ curve, config: { seed: 2, dryRun: true } });
    expect(result.report.allWithinBudget).toBe(true);
  });

  it("returns allWithinBudget=false for a curve with 20% errors", async () => {
    const curve = buildSyntheticCurve({
      sampleCount: 5,
      errorRateFraction: 0.2,
    });
    const result = await simulate({ curve, config: { seed: 3, dryRun: true } });
    expect(result.report.allWithinBudget).toBe(false);
  });

  it("uses synthetic curve when no curve or curveFile provided", async () => {
    const result = await simulate({ config: { dryRun: true } });
    expect(result.curve).toBeDefined();
    expect(result.plan).toBeDefined();
    expect(result.report).toBeDefined();
  });

  it("respects scale factor", async () => {
    const curve = buildSyntheticCurve({ sampleCount: 3 });
    const r1 = await simulate({ curve, config: { seed: 5, dryRun: true, scaleFactor: 1.0 } });
    const r2 = await simulate({ curve, config: { seed: 5, dryRun: true, scaleFactor: 2.0 } });
    expect(r2.report.totalRequests).toBeGreaterThan(r1.report.totalRequests);
  });

  it("calls requestHandler for every request in the plan", async () => {
    const curve = buildSyntheticCurve({ sampleCount: 2 });
    const handledIds = new Set<string>();
    const result = await simulate({
      curve,
      config: { seed: 6, dryRun: true },
      requestHandler: (req) => { handledIds.add(req.id); },
    });
    expect(handledIds.size).toBe(result.plan.requests.length);
  });

  it("invokes onProgress callback", async () => {
    const curve = buildSyntheticCurve({ sampleCount: 2 });
    let lastDone = -1;
    let lastTotal = -1;
    await simulate({
      curve,
      config: { seed: 7, dryRun: true },
      onProgress: (done, total) => { lastDone = done; lastTotal = total; },
    });
    expect(lastDone).toBeGreaterThan(0);
    expect(lastTotal).toBeGreaterThan(0);
    expect(lastDone).toBe(lastTotal);
  });
});

// ---------------------------------------------------------------------------
// Edge case: missing historical range
// ---------------------------------------------------------------------------

describe("simulate() – missing historical range", () => {
  it("emits SPARSE_RANGE warning for large gaps in sample data", async () => {
    // Normal samples at 60s intervals, then a huge 10-minute gap
    const samples = [
      makeSample(BASE_MS, "slots_list"),
      makeSample(BASE_MS + 60_000, "slots_list"),
      makeSample(BASE_MS + 120_000, "slots_list"),
      makeSample(BASE_MS + 720_000, "slots_list"), // 10-min gap
    ];
    const curve: TrafficCurve = {
      label: "sparse",
      startIso: new Date(BASE_MS).toISOString(),
      endIso: new Date(BASE_MS + 800_000).toISOString(),
      samples,
    };

    const result = await simulate({
      curve,
      config: { dryRun: true, maxDurationMs: 800_000 },
    });

    const sparseWarning = result.ingestionWarnings.find(
      (w) => w.code === "SPARSE_RANGE",
    );
    expect(sparseWarning).toBeDefined();
  });

  it("still produces a valid plan even with a sparse curve", async () => {
    const samples = [
      makeSample(BASE_MS, "booking_intent"),
      makeSample(BASE_MS + 3_600_000, "booking_intent"), // 1-hour gap
    ];
    const curve: TrafficCurve = {
      label: "sparse-big",
      startIso: new Date(BASE_MS).toISOString(),
      endIso: new Date(BASE_MS + 3_700_000).toISOString(),
      samples,
    };

    const result = await simulate({
      curve,
      config: { dryRun: true, maxDurationMs: 3_700_000 },
    });

    expect(result.plan).toBeDefined();
    expect(result.report).toBeDefined();
  });
});

// ---------------------------------------------------------------------------
// Edge case: unrealistic traffic mix
// ---------------------------------------------------------------------------

describe("simulate() – unrealistic traffic mix", () => {
  it("handles 100% error rate without crashing", async () => {
    const curve = buildSyntheticCurve({
      sampleCount: 3,
      errorRateFraction: 1.0,
    });
    const result = await simulate({
      curve,
      config: { seed: 8, dryRun: true },
    });
    expect(result.report.allWithinBudget).toBe(false);
  });

  it("handles 0% error rate (all-success)", async () => {
    const curve = buildSyntheticCurve({
      sampleCount: 3,
      errorRateFraction: 0,
    });
    const result = await simulate({
      curve,
      config: { seed: 9, dryRun: true },
    });
    expect(result.report.allWithinBudget).toBe(true);
  });

  it("handles very high request count without running out of memory", async () => {
    // Large scale – should complete without issue
    const curve = buildSyntheticCurve({ sampleCount: 5, peakRps: 1000 });
    const result = await simulate({
      curve,
      config: { seed: 10, dryRun: true, scaleFactor: 1.0 },
    });
    expect(result.plan.requests.length).toBeGreaterThan(0);
  });

  it("handles out-of-order samples (SAMPLES_REORDERED warning)", async () => {
    const curve: TrafficCurve = {
      label: "reordered",
      startIso: new Date(BASE_MS).toISOString(),
      endIso: new Date(BASE_MS + 200_000).toISOString(),
      samples: [
        makeSample(BASE_MS + 120_000, "checkout"),
        makeSample(BASE_MS, "checkout"),
        makeSample(BASE_MS + 60_000, "checkout"),
      ],
    };
    const result = await simulate({
      curve,
      config: { dryRun: true, maxDurationMs: 200_000 },
    });
    const warn = result.ingestionWarnings.find((w) => w.code === "SAMPLES_REORDERED");
    expect(warn).toBeDefined();
  });
});

// ---------------------------------------------------------------------------
// Edge case: network drop mid-run simulation (handler throws)
// ---------------------------------------------------------------------------

describe("simulate() – handler throws mid-run", () => {
  it("propagates handler errors in dry-run mode", async () => {
    const curve = buildSyntheticCurve({ sampleCount: 2, peakRps: 5 });
    let callCount = 0;

    await expect(
      simulate({
        curve,
        config: { seed: 11, dryRun: true },
        requestHandler: (req) => {
          callCount++;
          if (callCount === 3) throw new Error("Simulated network drop");
        },
      }),
    ).rejects.toThrow("Simulated network drop");
  });
});

// ---------------------------------------------------------------------------
// Safety in integration context
// ---------------------------------------------------------------------------

describe("simulate() – safety guardrails integration", () => {
  let savedNodeEnv: string | undefined;

  beforeEach(() => {
    savedNodeEnv = process.env.NODE_ENV;
  });

  afterEach(() => {
    if (savedNodeEnv === undefined) {
      delete process.env.NODE_ENV;
    } else {
      process.env.NODE_ENV = savedNodeEnv;
    }
  });

  it("throws SimulationSafetyError when NODE_ENV=production", async () => {
    process.env.NODE_ENV = "production";
    const curve = buildSyntheticCurve();
    await expect(
      simulate({ curve, config: { dryRun: true } }),
    ).rejects.toThrow(SimulationSafetyError);
  });
});

// ---------------------------------------------------------------------------
// ingestFromObject integration round-trip
// ---------------------------------------------------------------------------

describe("ingestFromObject round-trip", () => {
  it("round-trips through JSON serialization", () => {
    const curve = buildSyntheticCurve({ sampleCount: 3 });
    const serialized = JSON.parse(JSON.stringify(curve));
    const result = ingestFromObject(serialized);
    expect(result.curve.label).toBe(curve.label);
    expect(result.curve.samples.length).toBe(curve.samples.length);
  });
});
